-- =============================================================================
-- Tenancy foundation: one shared database, every business row belongs to one
-- merchant, and the database itself keeps merchants apart.
--
-- * public.merchants is the registry. Everything that existed before this
--   migration becomes Merchant #1; nothing is deleted or rewritten.
-- * Every tenant table gets merchant_id (not null, defaulting to the caller's
--   merchant) and a RESTRICTIVE row-level policy: a row can be read or written
--   only when merchant_id = current_merchant_id(). Restrictive policies are
--   AND-ed with the existing ones, so staff permissions keep working as before.
-- * Our SECURITY DEFINER functions are re-owned by app_owner, a role without
--   BYPASSRLS, so the same policy applies inside them: an existing function
--   cannot read or change another merchant's rows even if it forgets a filter.
-- * A short, listed set of functions must keep bypassing row-level security
--   (the merchant lookup itself, staff permission checks, Vault and auth.users
--   access). They stay owned by postgres, are recorded in
--   tenancy_exempt_functions, and filter by merchant explicitly.
-- * current_merchant_id() fails closed (null) when it cannot tell the
--   merchant; a null merchant sees no rows and cannot insert any.
-- * Business keys that were unique across the whole database (product SKU and
--   slug, customer phone, coupon code, settings key, ...) become unique per
--   merchant, so two merchants can each have customer 017xxxxxxxx.
--   Identifiers that come from outside and are used to route webhooks
--   (Shopify shop domain, store domains, payment references, website API keys,
--   ad account ids, courier event keys) stay unique across the platform.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. app_owner: owns the business functions, does not bypass row-level security
-- -----------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'app_owner') then
    create role app_owner nologin inherit nobypassrls;
  end if;
end $$;

-- postgres must be able to hand functions to app_owner and to replace them in
-- later migrations (CREATE OR REPLACE needs the owner's privileges).
grant app_owner to postgres with inherit true, set true;
-- Schema usage on auth (auth.uid(), auth.jwt()) comes through service_role.
-- BYPASSRLS is a role attribute and is never inherited through membership.
grant service_role to app_owner with inherit true, set false;
grant usage, create on schema public to app_owner;
grant usage on schema extensions to app_owner;
grant select, insert, update, delete on all tables in schema public to app_owner;
grant usage, select, update on all sequences in schema public to app_owner;
grant execute on all functions in schema public to app_owner;
alter default privileges for role postgres in schema public grant select, insert, update, delete on tables to app_owner;
alter default privileges for role postgres in schema public grant usage, select, update on sequences to app_owner;
alter default privileges for role postgres in schema public grant execute on functions to app_owner;

-- -----------------------------------------------------------------------------
-- 2. Platform registry
-- -----------------------------------------------------------------------------
create table public.merchants (
  id uuid primary key default gen_random_uuid(),
  number bigint generated by default as identity unique,
  name text not null check (length(trim(name)) between 1 and 120),
  slug text unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  status text not null default 'ACTIVE' check (status in ('ONBOARDING', 'ACTIVE', 'SUSPENDED', 'CLOSED')),
  status_reason text,
  is_demo boolean not null default false,
  owner_email text,
  phone text,
  notes text,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.merchants is 'Every business using the platform. Merchant #1 holds the data that existed before multi-tenancy.';
create trigger merchants_updated_at before update on public.merchants
  for each row execute function public.set_updated_at();

-- People who run the platform (Super Admin panel). Roles and permissions for
-- them are added by the Super Admin migration; this table only says who they are.
create table public.platform_staff (
  user_id uuid primary key references auth.users(id) on delete cascade,
  email text not null,
  full_name text not null default '',
  is_active boolean not null default true,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger platform_staff_updated_at before update on public.platform_staff
  for each row execute function public.set_updated_at();

-- Time-limited "view as merchant" sessions for platform support. VIEW is read
-- only (enforced by the row-level policies below); ASSIST may change data and
-- needs a second platform person's approval.
create table public.support_sessions (
  id uuid primary key default gen_random_uuid(),
  staff_user_id uuid not null references auth.users(id) on delete cascade,
  merchant_id uuid not null references public.merchants(id),
  mode text not null default 'VIEW' check (mode in ('VIEW', 'ASSIST')),
  permissions text[] not null default '{}',
  reason text not null check (length(trim(reason)) between 5 and 500),
  ticket_id uuid,
  approved_by uuid references auth.users(id),
  started_at timestamptz not null default now(),
  expires_at timestamptz not null,
  ended_at timestamptz,
  ended_by uuid,
  end_reason text,
  check (expires_at > started_at and expires_at <= started_at + interval '4 hours'),
  check (mode = 'VIEW' or approved_by is not null),
  check (approved_by is null or approved_by <> staff_user_id)
);
create index support_sessions_open_idx on public.support_sessions (staff_user_id, started_at desc) where ended_at is null;
create index support_sessions_merchant_idx on public.support_sessions (merchant_id, started_at desc);

-- Functions that keep bypassing row-level security, and why.
create table public.tenancy_exempt_functions (
  name text primary key,
  reason text not null
);

alter table public.merchants enable row level security;
alter table public.platform_staff enable row level security;
alter table public.support_sessions enable row level security;
alter table public.tenancy_exempt_functions enable row level security;
revoke all on public.platform_staff, public.support_sessions, public.tenancy_exempt_functions from anon, authenticated;
revoke insert, update, delete on public.merchants from anon, authenticated;

-- Merchant #1: the business that used this database before multi-tenancy.
insert into public.merchants (id, name, status)
values ('00000000-0000-4000-8000-000000000001',
        coalesce((select nullif(trim(value ->> 'name'), '') from public.settings where key = 'store'), 'Merchant #1'),
        'ACTIVE');

-- -----------------------------------------------------------------------------
-- 3. Which merchant is this request for?
-- -----------------------------------------------------------------------------
-- The open support session of the signed-in platform staff member, if any.
create or replace function public._support_session_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.id
  from public.support_sessions s
  join public.platform_staff ps on ps.user_id = s.staff_user_id and ps.is_active
  where coalesce(auth.jwt() ->> 'role', '') = 'authenticated'
    and s.staff_user_id = auth.uid()
    and s.ended_at is null
    and s.expires_at > now()
  order by s.started_at desc
  limit 1
$$;

-- Resolution order (first match wins, otherwise null = no access):
--   1. app.merchant_id, set by trusted server code (cron, migrations, the SQL
--      editor, tests, platform functions acting for a merchant). Ignored for
--      browser requests (anon / authenticated) unless the signed-in user is
--      active platform staff, whose platform functions set it deliberately.
--   2. Signed-in user: an open platform support session, else their staff profile.
--   3. x-merchant-id request header, for storefront visitors, customers and
--      edge functions (which derive it server-side). Staff can never use it to
--      switch merchant because step 2 answers for them first.
create or replace function public.current_merchant_id()
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_uid uuid;
  v_text text;
  v_id uuid;
begin
  v_text := nullif(current_setting('app.merchant_id', true), '');
  if v_text is not null
     and (v_role not in ('anon', 'authenticated')
          or (v_role = 'authenticated'
              and exists (select 1 from public.platform_staff ps where ps.user_id = auth.uid() and ps.is_active))) then
    if v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'INVALID_MERCHANT_CONTEXT: app.merchant_id is not a merchant id' using errcode = '22023';
    end if;
    return v_text::uuid;
  end if;

  if v_role = 'authenticated' then
    v_uid := auth.uid();
    if v_uid is not null then
      select s.merchant_id into v_id from public.support_sessions s where s.id = public._support_session_id();
      if v_id is not null then
        return v_id;
      end if;
      select p.merchant_id into v_id from public.profiles p where p.id = v_uid;
      if v_id is not null then
        return v_id;
      end if;
    end if;
  end if;

  if v_role in ('anon', 'authenticated', 'service_role') then
    v_text := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-merchant-id';
    if v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select m.id into v_id from public.merchants m where m.id = v_text::uuid and m.status <> 'CLOSED';
      return v_id;
    end if;
  end if;

  return null;
end;
$$;

-- True while the signed-in platform staff member is in a read-only support session.
create or replace function public._support_read_only()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select s.mode = 'VIEW' from public.support_sessions s where s.id = public._support_session_id()), false)
$$;

-- -----------------------------------------------------------------------------
-- 4. merchant_id on every tenant table + isolation policies
-- -----------------------------------------------------------------------------
-- Shared reference data (no merchant_id): the permission catalogue, the order
-- status machine, VoiceDrive packages and gateway health, and the platform
-- tables above.
create or replace function public._tenancy_global_tables()
returns text[]
language sql
immutable
as $$
  select array['permissions', 'order_status_transitions', 'pbx_packages', 'pbx_gateway_status',
               'merchants', 'platform_staff', 'support_sessions', 'tenancy_exempt_functions']
$$;

do $$
declare
  r record;
  v_first constant uuid := '00000000-0000-4000-8000-000000000001';
  v_check text;
begin
  for r in
    select c.relname
    from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
      and c.relname <> all (public._tenancy_global_tables())
    order by c.relname
  loop
    -- A constant default fills existing rows without rewriting them or firing
    -- triggers; afterwards new rows default to the caller's merchant.
    if r.relname = 'system_logs' then
      -- Platform-level errors (no merchant known yet) keep merchant_id null.
      execute format('alter table public.%I add column merchant_id uuid default %L references public.merchants(id)', r.relname, v_first);
    else
      execute format('alter table public.%I add column merchant_id uuid not null default %L references public.merchants(id)', r.relname, v_first);
    end if;
    execute format('alter table public.%I alter column merchant_id set default public.current_merchant_id()', r.relname);
    execute format('create index %I on public.%I (merchant_id)', left(r.relname, 45) || '_merchant_idx', r.relname);
    execute format('alter table public.%I enable row level security', r.relname);

    if r.relname = 'system_logs' then
      execute format($p$create policy tenant_isolation on public.%I as restrictive for all to public
        using (merchant_id is not distinct from (select public.current_merchant_id()))
        with check (merchant_id is not distinct from (select public.current_merchant_id()))$p$, r.relname);
    else
      -- Audit entries stay writable during a read-only support session;
      -- everything else is frozen for the support viewer.
      v_check := case when r.relname = 'audit_logs' then '' else ' and not (select public._support_read_only())' end;
      execute format($p$create policy tenant_isolation on public.%I as restrictive for all to public
        using (merchant_id = (select public.current_merchant_id()))
        with check (merchant_id = (select public.current_merchant_id())%s)$p$, r.relname, v_check);
      if r.relname <> 'audit_logs' then
        execute format($p$create policy tenant_read_only_delete on public.%I as restrictive for delete to public
          using (not (select public._support_read_only()))$p$, r.relname);
      end if;
    end if;

    execute format('create policy app_owner_all on public.%I for all to app_owner using (true) with check (true)', r.relname);
  end loop;

  -- Shared reference data: app_owner may read and maintain it like before.
  for r in
    select unnest(array['permissions', 'order_status_transitions', 'pbx_packages', 'pbx_gateway_status']) as relname
  loop
    execute format('alter table public.%I enable row level security', r.relname);
    execute format('create policy app_owner_all on public.%I for all to app_owner using (true) with check (true)', r.relname);
  end loop;
end $$;

-- Staff and our functions can read their own merchant's registry row.
create policy merchants_read_own on public.merchants for select to authenticated, app_owner
  using (id = (select public.current_merchant_id()));

-- -----------------------------------------------------------------------------
-- 5. Business keys unique per merchant
-- -----------------------------------------------------------------------------
