alter table public.customers add constraint customers_phone_key unique (merchant_id, phone);
alter table public.customers drop constraint customers_auth_user_id_key;
alter table public.customers add constraint customers_auth_user_id_key unique (merchant_id, auth_user_id);
alter table public.finance_categories drop constraint finance_categories_code_key;
alter table public.finance_categories add constraint finance_categories_code_key unique (merchant_id, code);
alter table public.hr_departments drop constraint hr_departments_name_key;
alter table public.hr_departments add constraint hr_departments_name_key unique (merchant_id, name);
alter table public.hr_shifts drop constraint hr_shifts_name_key;
alter table public.hr_shifts add constraint hr_shifts_name_key unique (merchant_id, name);
alter table public.hr_employees drop constraint hr_employees_employee_code_key;
alter table public.hr_employees add constraint hr_employees_employee_code_key unique (merchant_id, employee_code);
alter table public.hr_holidays drop constraint hr_holidays_pkey;
alter table public.hr_holidays add constraint hr_holidays_pkey primary key (merchant_id, holiday_date);
alter table public.integration_credentials drop constraint integration_credentials_pkey;
alter table public.integration_credentials add constraint integration_credentials_pkey primary key (merchant_id, key);
alter table public.notification_logs drop constraint notification_logs_dedupe_key_key;
alter table public.notification_logs add constraint notification_logs_dedupe_key_key unique (merchant_id, dedupe_key);
alter table public.orders drop constraint orders_review_status_fkey;
alter table public.order_review_statuses drop constraint order_review_statuses_pkey;
alter table public.order_review_statuses add constraint order_review_statuses_pkey primary key (merchant_id, code);
alter table public.orders add constraint orders_review_status_fkey
  foreign key (merchant_id, review_status) references public.order_review_statuses (merchant_id, code);
alter table public.order_sources drop constraint order_sources_pkey;
