  where status in ('OPEN', 'CONTACTED');
drop index public.pbx_businesses_one_primary;
create unique index pbx_businesses_one_primary on public.pbx_businesses (merchant_id) where is_primary;

-- Upserts that named the old global keys.
create or replace function pg_temp.tenancy_patch(p_fn regprocedure, p_from text, p_to text)
returns void
language plpgsql
as $$
declare
  v_old text := pg_get_functiondef(p_fn);
  v_new text := replace(v_old, p_from, p_to);
begin
  if v_new = v_old then
    raise exception 'tenancy: % does not contain "%"', p_fn, p_from;
  end if;
  execute v_new;
end;
$$;

select pg_temp.tenancy_patch('public.capture_checkout_lead(jsonb)', 'on conflict (visitor_id)', 'on conflict (merchant_id, visitor_id)');
select pg_temp.tenancy_patch('public.storefront_cart_sync(text,text,jsonb,jsonb)', 'on conflict (visitor_id)', 'on conflict (merchant_id, visitor_id)');
select pg_temp.tenancy_patch('public.hr_holiday_save(date,text,boolean)', 'on conflict (holiday_date)', 'on conflict (merchant_id, holiday_date)');
select pg_temp.tenancy_patch('public._enqueue_order_notification(uuid,public.notification_event,text,jsonb)', 'on conflict (dedupe_key)', 'on conflict (merchant_id, dedupe_key)');
select pg_temp.tenancy_patch('public.admin_save_review_status(jsonb)', 'on conflict (code)', 'on conflict (merchant_id, code)');
select pg_temp.tenancy_patch('public.admin_save_order_tag(text,text)', 'on conflict (name)', 'on conflict (merchant_id, name)');
select pg_temp.tenancy_patch('public.order_set_tags(uuid[],text[],text[])', 'on conflict (name)', 'on conflict (merchant_id, name)');
select pg_temp.tenancy_patch('public._log_system_event(text,text,text,text,jsonb)', 'on conflict (fingerprint)', 'on conflict (merchant_id, fingerprint)');

-- -----------------------------------------------------------------------------
-- 6. Functions that keep bypassing row-level security filter by merchant
-- -----------------------------------------------------------------------------
create or replace function public._device_ok(p_profile uuid, p_role text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p_role = 'OWNER'
    or not coalesce((select (s.value ->> 'enabled')::boolean
                     from public.settings s join public.profiles p on p.merchant_id = s.merchant_id
                     where p.id = p_profile and s.key = 'device_approval'), false)
    or exists (
      select 1 from public.staff_device_sessions ds
      join public.staff_devices d on d.id = ds.device_id
      where ds.session_id = public._jwt_session() and d.profile_id = p_profile and d.status = 'APPROVED')
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
      select 1 from public.profiles p join public.roles r on r.id = p.role_id
      where p.id = auth.uid() and p.merchant_id = public.current_merchant_id()
        and p.is_active and public._device_ok(p.id, r.code))
    or exists (
      select 1 from public.support_sessions s
      where s.id = public._support_session_id() and s.merchant_id = public.current_merchant_id())
$$;

-- Platform support sessions get every *.view permission; ASSIST sessions also
-- get the permissions approved for that session.
create or replace function public.has_permission(p_code text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
      select 1
      from public.profiles p
      join public.roles r on r.id = p.role_id
      where p.id = auth.uid()
        and p.merchant_id = public.current_merchant_id()
        and p.is_active
        and public._device_ok(p.id, r.code)
        and (
          r.code = 'OWNER'
          or exists (
            select 1
            from public.role_permissions rp
            join public.permissions pm on pm.id = rp.permission_id
            where rp.role_id = r.id and pm.code = p_code
          )
        ))
    or exists (
      select 1 from public.support_sessions s
      where s.id = public._support_session_id()
        and s.merchant_id = public.current_merchant_id()
        and (p_code like '%.view' or (s.mode = 'ASSIST' and p_code = any (s.permissions))))
$$;

create or replace function public.current_role_code()
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select r.code
  from public.profiles p
  join public.roles r on r.id = p.role_id
  where p.id = auth.uid() and p.is_active and p.merchant_id = public.current_merchant_id()
$$;

-- auth.users is outside our schema; these two helpers are the only way our
-- business functions read it.
create or replace function public._auth_user(p_user_id uuid)
returns table (id uuid, email text, full_name text)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select u.id, u.email::text, coalesce(u.raw_user_meta_data ->> 'full_name', '')
  from auth.users u where u.id = p_user_id
$$;
revoke execute on function public._auth_user(uuid) from public, anon, authenticated;
grant execute on function public._auth_user(uuid) to service_role, app_owner;

-- The merchant a staff account works for (any merchant), or null.
create or replace function public._staff_merchant(p_user_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select merchant_id from public.profiles where id = p_user_id
$$;
revoke execute on function public._staff_merchant(uuid) from public, anon, authenticated;
grant execute on function public._staff_merchant(uuid) to service_role, app_owner;

create or replace function public.admin_set_user_role(p_user_id uuid, p_role_code text, p_is_active boolean default true)
returns public.profiles
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role public.roles;
  v_profile public.profiles;
  v_my_role text := public.current_role_code();
  v_my_rank int;
  v_merchant uuid := public.current_merchant_id();
  v_other uuid;
begin
  perform public.require_permission('users.manage');
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: choose the merchant first' using errcode = '42501';
  end if;

  select * into v_role from public.roles where code = upper(p_role_code);
  if not found then
    raise exception 'VALIDATION: unknown role %', p_role_code using errcode = '22023';
  end if;

  -- A login works for one business; it cannot be pulled into a second one.
  v_other := public._staff_merchant(p_user_id);
  if v_other is not null and v_other <> v_merchant then
    raise exception 'VALIDATION: this account already belongs to another business' using errcode = '22023';
  end if;

  if not public.is_system_context() then
    if p_user_id = auth.uid() then
      raise exception 'PERMISSION_DENIED: you cannot change your own role or status' using errcode = '42501';
    end if;
    if v_role.code = 'OWNER' and v_my_role <> 'OWNER' then
      raise exception 'PERMISSION_DENIED: only an owner can grant the OWNER role' using errcode = '42501';
    end if;
    if exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
               where p.id = p_user_id and r.code = 'OWNER') and v_my_role <> 'OWNER' then
      raise exception 'PERMISSION_DENIED: only an owner can modify another owner' using errcode = '42501';
    end if;
    -- Whoever holds users.manage can only hand out, or take away, roles up to their own rank.
    if v_my_role <> 'OWNER' then
      v_my_rank := coalesce((select rank from public.roles where code = v_my_role), 0);
      if v_role.rank > v_my_rank then
        raise exception 'PERMISSION_DENIED: you cannot grant a role above your own' using errcode = '42501';
      end if;
      if exists (select 1 from public.profiles p join public.roles r on r.id = p.role_id
                 where p.id = p_user_id and r.rank > v_my_rank) then
        raise exception 'PERMISSION_DENIED: you cannot change someone with a higher role than yours' using errcode = '42501';
      end if;
    end if;
  end if;

  select * into v_profile from public.profiles where id = p_user_id for update;
  if not found then
    insert into public.profiles(id, email, full_name, role_id, is_active)
    select u.id, u.email, u.full_name, v_role.id, p_is_active
    from public._auth_user(p_user_id) u
    returning * into v_profile;
    if v_profile.id is null then
      raise exception 'NOT_FOUND: auth user % does not exist', p_user_id using errcode = 'P0002';
    end if;
  else
    -- Never leave the business without an active owner.
    if (select code from public.roles where id = v_profile.role_id) = 'OWNER'
       and (v_role.code <> 'OWNER' or not p_is_active)
       and (select count(*) from public.profiles p join public.roles r on r.id = p.role_id
            where r.code = 'OWNER' and p.is_active and p.id <> p_user_id) = 0 then
      raise exception 'VALIDATION: at least one active owner is required' using errcode = '22023';
    end if;
    update public.profiles set role_id = v_role.id, is_active = p_is_active
    where id = p_user_id returning * into v_profile;
  end if;

  perform public.log_audit('user.role_changed', 'profile', p_user_id::text, null,
    jsonb_build_object('role', v_role.code, 'is_active', p_is_active));
  return v_profile;
end;
$$;

create or replace function public.grant_owner(p_email text)
returns public.profiles
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED: grant_owner can only be run from the SQL editor or service role'
      using errcode = '42501';
  end if;
  v_user_id := public.find_auth_user_id(p_email);
  if v_user_id is null then
    raise exception 'NOT_FOUND: no auth user with email %', p_email using errcode = 'P0002';
  end if;
  return public.admin_set_user_role(v_user_id, 'OWNER', true);
end;
$$;

-- Vault-backed credentials: each merchant's secrets live under its own name
-- and are only reachable inside that merchant's context.
create or replace function public.integration_secret_store(p_key text, p_value jsonb, p_hint text, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
  v_name text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this credential' using errcode = '42501';
  end if;
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: credentials must be an object' using errcode = '22023';
  end if;
  v_name := 'integration:' || v_merchant::text || ':' || p_key;
  select secret_id into v_secret from public.integration_credentials where merchant_id = v_merchant and key = p_key;
  if v_secret is null then
    select id into v_secret from vault.secrets where name = v_name;
  end if;
  if v_secret is null then
    v_secret := vault.create_secret(p_value::text, v_name, 'Integration credentials');
  else
    perform vault.update_secret(v_secret, p_value::text);
  end if;
  insert into public.integration_credentials(merchant_id, key, secret_id, hint, connected_by, connected_at, updated_at)
  values (v_merchant, p_key, v_secret, p_hint, p_actor, now(), now())
  on conflict (merchant_id, key) do update set secret_id = excluded.secret_id, hint = excluded.hint,
    connected_by = excluded.connected_by, connected_at = now(), updated_at = now();
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'integration.connected', 'integration', p_key, jsonb_build_object('hint', p_hint));
end;
$$;

create or replace function public.integration_secret_get(p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    return null;
  end if;
  select secret_id into v_secret from public.integration_credentials
  where merchant_id = v_merchant and key = p_key and hint is not null;
  if v_secret is null then
    return null;
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets where id = v_secret;
  return nullif(nullif(v_value, ''), '{}')::jsonb;
end;
$$;

create or replace function public.integration_secret_clear(p_key text, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this credential' using errcode = '42501';
  end if;
  select secret_id into v_secret from public.integration_credentials where merchant_id = v_merchant and key = p_key;
  if v_secret is not null then
    perform vault.update_secret(v_secret, '{}');
  end if;
  update public.integration_credentials set hint = null, updated_at = now() where merchant_id = v_merchant and key = p_key;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'integration.disconnected', 'integration', p_key, '{}'::jsonb);
end;
$$;

-- The courier must belong to the merchant whose context this is.
create or replace function public._courier_in_context(p_courier_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
begin
  if v_merchant is null then
    raise exception 'MERCHANT_REQUIRED: no merchant context for this courier' using errcode = '42501';
  end if;
  if not exists (select 1 from public.couriers where id = p_courier_id and merchant_id = v_merchant) then
    raise exception 'NOT_FOUND: courier not found' using errcode = 'P0002';
  end if;
  return v_merchant;
end;
$$;
revoke execute on function public._courier_in_context(uuid) from public, anon, authenticated;

create or replace function public.courier_credentials_store(p_courier_id uuid, p_provider text, p_credentials jsonb, p_hint text, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid;
  v_secret uuid;
  v_name text := 'courier:' || p_courier_id::text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  v_merchant := public._courier_in_context(p_courier_id);
  if p_credentials is null or jsonb_typeof(p_credentials) <> 'object' then
    raise exception 'VALIDATION: credentials must be an object' using errcode = '22023';
  end if;
  select secret_id into v_secret from public.courier_credentials where courier_id = p_courier_id;
  if v_secret is null then
    select id into v_secret from vault.secrets where name = v_name;
  end if;
  if v_secret is null then
    v_secret := vault.create_secret(p_credentials::text, v_name, 'Courier API credentials');
  else
    perform vault.update_secret(v_secret, p_credentials::text);
  end if;
  insert into public.courier_credentials(merchant_id, courier_id, provider, secret_id, hint, connected_by, connected_at, updated_at)
  values (v_merchant, p_courier_id, p_provider, v_secret, p_hint, p_actor, now(), now())
  on conflict (courier_id) do update set provider = excluded.provider, secret_id = excluded.secret_id,
    hint = excluded.hint, connected_by = excluded.connected_by, updated_at = now();
  update public.couriers set provider = p_provider, api_enabled = true, api_status = 'CONNECTED', api_checked_at = now(),
    config = config || jsonb_build_object('credential_hint', p_hint, 'connected_at', now())
  where id = p_courier_id and merchant_id = v_merchant;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'courier.connected', 'couriers', p_courier_id::text, jsonb_build_object('provider', p_provider, 'hint', p_hint));
end;
$$;

create or replace function public.courier_credentials_get(p_courier_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_secret uuid;
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  perform public._courier_in_context(p_courier_id);
  select secret_id into v_secret from public.courier_credentials where courier_id = p_courier_id;
  if v_secret is null then
    return null;
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets where id = v_secret;
  return nullif(nullif(v_value, ''), '{}')::jsonb;
end;
$$;

create or replace function public.courier_credentials_clear(p_courier_id uuid, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid;
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  v_merchant := public._courier_in_context(p_courier_id);
  select secret_id into v_secret from public.courier_credentials where courier_id = p_courier_id;
  if v_secret is not null then
    perform vault.update_secret(v_secret, '{}');
  end if;
  update public.courier_credentials set hint = null, updated_at = now() where courier_id = p_courier_id;
  update public.couriers set api_enabled = false, api_status = 'NOT_CONFIGURED',
    config = config - 'credential_hint' - 'connected_at'
  where id = p_courier_id;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'courier.disconnected', 'couriers', p_courier_id::text, '{}'::jsonb);
end;
$$;

create or replace function public.courier_webhook_secret_get(p_courier_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  perform public._courier_in_context(p_courier_id);
  select decrypted_secret into v_value from vault.decrypted_secrets where name = 'courier-webhook:' || p_courier_id::text;
  return nullif(v_value, '');
end;
$$;

create or replace function public.courier_webhook_secret_set(p_courier_id uuid, p_secret text, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid;
  v_secret uuid;
  v_name text := 'courier-webhook:' || p_courier_id::text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_secret is null or length(p_secret) < 16 or length(p_secret) > 200 then
    raise exception 'VALIDATION: the webhook secret must be 16 to 200 characters' using errcode = '22023';
  end if;
  v_merchant := public._courier_in_context(p_courier_id);
  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_secret, v_name, 'Courier webhook secret');
  else
    perform vault.update_secret(v_secret, p_secret);
  end if;
  update public.couriers set config = config || jsonb_build_object('webhook_secret_hint', '••••' || right(p_secret, 4),
    'webhook_secret_set_at', now()) where id = p_courier_id;
  insert into public.audit_logs(merchant_id, actor_id, actor_email, action, entity_type, entity_id, metadata)
  values (v_merchant, p_actor, (select email from public.profiles where id = p_actor and merchant_id = v_merchant),
          'courier.webhook_secret_set', 'couriers', p_courier_id::text, '{}'::jsonb);
end;
$$;

-- Cached gateway access tokens are kept per merchant (each merchant's own
-- bKash account); without a merchant they belong to the platform.
create or replace function public.gateway_token_get(p_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
  v_value text;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  select decrypted_secret into v_value from vault.decrypted_secrets
  where name = 'gateway-token:' || coalesce(v_merchant::text || ':', 'platform:') || p_key;
  return nullif(v_value, '')::jsonb;
end;
$$;

create or replace function public.gateway_token_put(p_key text, p_value jsonb)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_merchant uuid := public.current_merchant_id();
  v_name text;
  v_secret uuid;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_key !~ '^[a-z0-9_]{2,40}$' or jsonb_typeof(p_value) <> 'object' then
    raise exception 'VALIDATION: bad gateway token' using errcode = '22023';
  end if;
  v_name := 'gateway-token:' || coalesce(v_merchant::text || ':', 'platform:') || p_key;
  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_value::text, v_name, 'Payment gateway access token (expires on its own)');
  else
    perform vault.update_secret(v_secret, p_value::text);
  end if;
end;
$$;

-- Scheduled-task health is platform-wide (pg_cron has no merchants); the rest
-- of system_status runs under the caller's merchant.
create or replace function public._cron_health()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_cron jsonb;
begin
  if to_regclass('cron.job_run_details') is null then
    return null;
  end if;
  execute $q$
    select jsonb_build_object(
      'failed', count(*) filter (where status = 'failed'), 'runs', count(*), 'last', max(end_time),
      'latest_failed', (select count(*) from (select distinct on (jobid) status from cron.job_run_details
                                               where start_time > now() - interval '24 hours' order by jobid, start_time desc) x
                        where x.status = 'failed'))
    from cron.job_run_details where start_time > now() - interval '24 hours'
  $q$ into v_cron;
  return v_cron;
end;
$$;
revoke execute on function public._cron_health() from public, anon, authenticated;
grant execute on function public._cron_health() to service_role, app_owner;

create or replace function public.system_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v jsonb := '[]'::jsonb;
  v_n1 bigint;
  v_n2 bigint;
  v_at timestamptz;
  v_cron jsonb;
begin
  perform public.require_permission('settings.view');

  v := v || jsonb_build_object('key', 'database', 'name', 'Database', 'status', 'ok', 'detail', 'Responding', 'at', now());

  select count(*) filter (where status = 'FAILED' and updated_at > now() - interval '24 hours'),
         count(*) filter (where status = 'PENDING' and next_attempt_at < now() - interval '15 minutes'),
         max(done_at)
    into v_n1, v_n2, v_at from public.channel_sync_jobs;
  v := v || jsonb_build_object('key', 'store_sync', 'name', 'Store sync jobs',
    'status', case when v_n2 > 0 then 'warn' when v_n1 > 0 then 'warn' else 'ok' end,
    'detail', case when v_n2 > 0 then format('%s job(s) overdue', v_n2) when v_n1 > 0 then format('%s failed in 24 h', v_n1) else 'Running normally' end,
    'at', v_at);

  select count(*) filter (where status in ('ERROR')), max(last_sync_at) into v_n1, v_at
  from public.sales_channels where status <> 'DISCONNECTED';
  v := v || jsonb_build_object('key', 'channels', 'name', 'Connected stores',
    'status', case when v_n1 > 0 then 'down' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s store(s) with errors', v_n1) when v_at is null then 'No store connected' else 'Connected' end,
    'at', v_at);

  select count(*) filter (where result = 'FAILED' and received_at > now() - interval '24 hours'), max(received_at) into v_n1, v_at
  from public.courier_webhook_events;
  v := v || jsonb_build_object('key', 'courier_webhooks', 'name', 'Courier webhooks',
    'status', case when v_n1 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s failed in 24 h', v_n1) when v_at is null then 'Nothing received yet' else 'Receiving updates' end,
    'at', v_at);

  select count(*) filter (where status = 'FAILED' and created_at > now() - interval '24 hours'),
         count(*) filter (where status = 'QUEUED' and next_attempt_at < now() - interval '15 minutes'),
         max(sent_at)
    into v_n1, v_n2, v_at from public.notification_logs;
  v := v || jsonb_build_object('key', 'messages', 'name', 'SMS & notifications',
    'status', case when v_n2 > 0 then 'warn' when v_n1 > 0 then 'warn' when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_n2 > 0 then format('%s message(s) waiting too long', v_n2) when v_n1 > 0 then format('%s failed in 24 h', v_n1)
      when v_at is null then 'Nothing sent yet' else 'Sending' end,
    'at', v_at);

  select count(*) filter (where created_at > now() - interval '24 hours'), max(created_at) into v_n1, v_at from public.payment_events;
  v := v || jsonb_build_object('key', 'payments', 'name', 'Payment gateways',
    'status', case when v_at is null then 'idle' else 'ok' end,
    'detail', case when v_at is null then 'No gateway events yet' else format('%s event(s) in 24 h', v_n1) end, 'at', v_at);

  select count(*) filter (where level = 'ERROR' and resolved_at is null and last_seen_at > now() - interval '24 hours'),
         max(last_seen_at) filter (where level = 'ERROR')
    into v_n1, v_at from public.system_logs;
  v := v || jsonb_build_object('key', 'errors', 'name', 'Application errors',
    'status', case when v_n1 > 0 then 'warn' else 'ok' end,
    'detail', case when v_n1 > 0 then format('%s unresolved error(s) in 24 h', v_n1) else 'No unresolved errors in 24 h' end, 'at', v_at);

  -- A rare "job startup timeout" is retried by the next run; warn only when
  -- a job's latest run failed or failures are more than 1 in 20.
  v_cron := public._cron_health();
  if v_cron is not null then
    v := v || jsonb_build_object('key', 'cron', 'name', 'Scheduled tasks',
      'status', case when (v_cron ->> 'latest_failed')::int > 0 or (v_cron ->> 'failed')::int * 20 > (v_cron ->> 'runs')::int then 'warn'
        when v_cron ->> 'last' is null then 'idle' else 'ok' end,
      'detail', case when v_cron ->> 'last' is null then 'No runs in 24 h'
        when (v_cron ->> 'failed')::int > 0 then format('%s of %s runs failed in 24 h — each was retried on its next run', v_cron ->> 'failed', v_cron ->> 'runs')
        else format('%s runs in 24 h, all on schedule', v_cron ->> 'runs') end,
      'at', v_cron ->> 'last');
  end if;

  return jsonb_build_object('checked_at', now(), 'components', v);
end;
$$;

-- -----------------------------------------------------------------------------
-- 7. Scheduled jobs run once per merchant, each inside that merchant's context
-- -----------------------------------------------------------------------------
create or replace function public.for_each_merchant(p_job text)
returns jsonb
language plpgsql
set search_path = public, pg_temp
as $$
declare
  m record;
  v_runs int := 0;
  v_failed int := 0;
begin
  if not public.is_system_context() then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_job not in ('retry_courier_webhooks', 'expire_unpaid_advance_orders', 'pbx_sweep') then
    raise exception 'VALIDATION: unknown job %', p_job using errcode = '22023';
  end if;
  for m in select id from public.merchants where status <> 'CLOSED' order by number loop
    perform set_config('app.merchant_id', m.id::text, true);
    v_runs := v_runs + 1;
    -- One merchant's failure is logged for that merchant and does not stop the others.
    begin
      execute format('select public.%I()', p_job);
    exception when others then
      v_failed := v_failed + 1;
      perform public._log_system_event('ERROR', 'JOB', p_job, sqlerrm,
        jsonb_build_object('merchant_id', m.id, 'sqlstate', sqlstate));
    end;
  end loop;
  perform set_config('app.merchant_id', '', true);
  return jsonb_build_object('job', p_job, 'merchants', v_runs, 'failed', v_failed);
end;
$$;
revoke execute on function public.for_each_merchant(text) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('expire-unpaid-advance-orders', '*/15 * * * *', $c$select public.for_each_merchant('expire_unpaid_advance_orders')$c$);
    perform cron.schedule('courier-webhook-retry', '*/5 * * * *', $c$select public.for_each_merchant('retry_courier_webhooks')$c$);
    perform cron.schedule('voicedrive-sweep', '* * * * *', $c$select public.for_each_merchant('pbx_sweep')$c$);
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- 8. Storage: files live under "<merchant id>/..." and only that merchant's
--    staff can reach them (product images stay publicly readable by URL).
-- -----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'product images staff upload') then
    alter policy "product images staff upload" on storage.objects
      with check (bucket_id = 'product-images' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
                  and (select public.has_permission('products.manage')));
    alter policy "product images staff update" on storage.objects
      using (bucket_id = 'product-images' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and (select public.has_permission('products.manage')));
    alter policy "product images staff delete" on storage.objects
      using (bucket_id = 'product-images' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and (select public.has_permission('products.manage')));
    alter policy "order files read" on storage.objects
      using (bucket_id = 'order-files' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and (select public.has_permission('orders.view')));
    alter policy "order files write" on storage.objects
      with check (bucket_id = 'order-files' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
                  and (select public.has_permission('orders.update')));
    alter policy "order files delete" on storage.objects
      using (bucket_id = 'order-files' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and (select public.has_permission('orders.update')));
    alter policy "documents read" on storage.objects
      using (bucket_id = 'documents' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and ((select public.has_permission('finance.view')) or (select public.has_permission('purchases.view'))));
    alter policy "documents write" on storage.objects
      with check (bucket_id = 'documents' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
                  and ((select public.has_permission('finance.manage')) or (select public.has_permission('purchases.manage'))));
    alter policy "documents delete" on storage.objects
      using (bucket_id = 'documents' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and (select public.has_permission('finance.manage')));
    alter policy "courier invoices read" on storage.objects
      using (bucket_id = 'courier-invoices' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
             and ((select public.has_permission('couriers.view')) or (select public.has_permission('finance.view'))));
    alter policy "courier invoices write" on storage.objects
      with check (bucket_id = 'courier-invoices' and (storage.foldername(name))[1] = (select public.current_merchant_id())::text
                  and (select public.has_permission('couriers.manage')));
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- 9. Defaults a new merchant starts with
-- -----------------------------------------------------------------------------
create or replace function public._merchant_seed_defaults(p_merchant uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
-- Default rows a new merchant starts with: the built-in roles and their
-- permissions, order review statuses and sources, finance categories, fraud
-- rules, delivery zones, the "Own delivery" courier, notification templates and
-- settings. Generated from a database with only the migrations applied, so a
-- new merchant never receives another merchant's data or configuration.
-- Runs inside that merchant's context; existing rows are left untouched.
declare
  v_counts jsonb := '{}'::jsonb;
  v_n int;
begin
  if public.current_merchant_id() is distinct from p_merchant then
    raise exception 'PERMISSION_DENIED: defaults can only be seeded inside the merchant''s own context' using errcode = '42501';
  end if;

  insert into public.roles (merchant_id, code, name, description, is_system, rank)
  select p_merchant, d.code, d.name, d.description, d.is_system, d.rank
  from jsonb_populate_recordset(null::public.roles, $d$[{"code": "OWNER", "name": "Owner", "rank": 100, "is_system": true, "description": "Full access to everything"}, {"code": "ADMIN", "name": "Admin", "rank": 90, "is_system": true, "description": "Runs the store: orders, catalog, stock, production, reports and settings"}, {"code": "MANAGER", "name": "Manager", "rank": 70, "is_system": true, "description": "Day-to-day operations across orders, stock and production"}, {"code": "FINANCE_MANAGER", "name": "Finance manager", "rank": 50, "is_system": true, "description": "Income, expenses, refunds and profit reports"}, {"code": "INVENTORY_MANAGER", "name": "Inventory manager", "rank": 50, "is_system": true, "description": "Products, stock, purchasing and adjustments"}, {"code": "ORDER_MANAGER", "name": "Order manager", "rank": 50, "is_system": true, "description": "Orders, customers, couriers and fraud review"}, {"code": "PRODUCTION_MANAGER", "name": "Production manager", "rank": 50, "is_system": true, "description": "Production, quality check and packing"}, {"code": "VIEWER", "name": "Viewer", "rank": 10, "is_system": true, "description": "Read-only access"}]$d$::jsonb) d
  where not exists (select 1 from public.roles r where r.merchant_id = p_merchant and r.code = d.code);
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('roles', v_n);

  insert into public.role_permissions (merchant_id, role_id, permission_id)
  select p_merchant, r.id, p.id
  from jsonb_to_recordset($d$[{"role": "ADMIN", "permission": "audit.view"}, {"role": "ADMIN", "permission": "coupons.manage"}, {"role": "ADMIN", "permission": "couriers.manage"}, {"role": "ADMIN", "permission": "couriers.view"}, {"role": "ADMIN", "permission": "customers.manage"}, {"role": "ADMIN", "permission": "customers.view"}, {"role": "ADMIN", "permission": "dashboard.view"}, {"role": "ADMIN", "permission": "devices.manage"}, {"role": "ADMIN", "permission": "finance.view"}, {"role": "ADMIN", "permission": "fraud.review"}, {"role": "ADMIN", "permission": "fraud.rules"}, {"role": "ADMIN", "permission": "fraud.view"}, {"role": "ADMIN", "permission": "hr.manage"}, {"role": "ADMIN", "permission": "hr.view"}, {"role": "ADMIN", "permission": "inventory.adjust"}, {"role": "ADMIN", "permission": "inventory.view"}, {"role": "ADMIN", "permission": "marketing.manage"}, {"role": "ADMIN", "permission": "marketing.view"}, {"role": "ADMIN", "permission": "orders.assign"}, {"role": "ADMIN", "permission": "orders.block"}, {"role": "ADMIN", "permission": "orders.cancel"}, {"role": "ADMIN", "permission": "orders.create"}, {"role": "ADMIN", "permission": "orders.export"}, {"role": "ADMIN", "permission": "orders.fulfill"}, {"role": "ADMIN", "permission": "orders.override"}, {"role": "ADMIN", "permission": "orders.price_override"}, {"role": "ADMIN", "permission": "orders.status"}, {"role": "ADMIN", "permission": "orders.update"}, {"role": "ADMIN", "permission": "orders.view"}, {"role": "ADMIN", "permission": "payments.record"}, {"role": "ADMIN", "permission": "payments.verify"}, {"role": "ADMIN", "permission": "pbx.call"}, {"role": "ADMIN", "permission": "pbx.manage"}, {"role": "ADMIN", "permission": "production.manage"}, {"role": "ADMIN", "permission": "production.view"}, {"role": "ADMIN", "permission": "products.manage"}, {"role": "ADMIN", "permission": "products.view"}, {"role": "ADMIN", "permission": "purchases.manage"}, {"role": "ADMIN", "permission": "purchases.view"}, {"role": "ADMIN", "permission": "reports.export"}, {"role": "ADMIN", "permission": "reports.view"}, {"role": "ADMIN", "permission": "settings.manage"}, {"role": "ADMIN", "permission": "settings.view"}, {"role": "ADMIN", "permission": "shipments.manage"}, {"role": "ADMIN", "permission": "sms.manage"}, {"role": "ADMIN", "permission": "sms.view"}, {"role": "ADMIN", "permission": "support.manage"}, {"role": "FINANCE_MANAGER", "permission": "couriers.view"}, {"role": "FINANCE_MANAGER", "permission": "customers.view"}, {"role": "FINANCE_MANAGER", "permission": "dashboard.view"}, {"role": "FINANCE_MANAGER", "permission": "finance.manage"}, {"role": "FINANCE_MANAGER", "permission": "finance.view"}, {"role": "FINANCE_MANAGER", "permission": "marketing.view"}, {"role": "FINANCE_MANAGER", "permission": "orders.view"}, {"role": "FINANCE_MANAGER", "permission": "payments.record"}, {"role": "FINANCE_MANAGER", "permission": "payments.verify"}, {"role": "FINANCE_MANAGER", "permission": "purchases.view"}, {"role": "FINANCE_MANAGER", "permission": "refunds.manage"}, {"role": "FINANCE_MANAGER", "permission": "reports.export"}, {"role": "FINANCE_MANAGER", "permission": "reports.view"}, {"role": "FINANCE_MANAGER", "permission": "sms.view"}, {"role": "INVENTORY_MANAGER", "permission": "dashboard.view"}, {"role": "INVENTORY_MANAGER", "permission": "inventory.adjust"}, {"role": "INVENTORY_MANAGER", "permission": "inventory.view"}, {"role": "INVENTORY_MANAGER", "permission": "products.manage"}, {"role": "INVENTORY_MANAGER", "permission": "products.view"}, {"role": "INVENTORY_MANAGER", "permission": "purchases.manage"}, {"role": "INVENTORY_MANAGER", "permission": "purchases.view"}, {"role": "INVENTORY_MANAGER", "permission": "reports.view"}, {"role": "MANAGER", "permission": "couriers.view"}, {"role": "MANAGER", "permission": "customers.manage"}, {"role": "MANAGER", "permission": "customers.view"}, {"role": "MANAGER", "permission": "dashboard.view"}, {"role": "MANAGER", "permission": "fraud.review"}, {"role": "MANAGER", "permission": "fraud.view"}, {"role": "MANAGER", "permission": "hr.view"}, {"role": "MANAGER", "permission": "inventory.adjust"}, {"role": "MANAGER", "permission": "inventory.view"}, {"role": "MANAGER", "permission": "marketing.view"}, {"role": "MANAGER", "permission": "orders.assign"}, {"role": "MANAGER", "permission": "orders.block"}, {"role": "MANAGER", "permission": "orders.cancel"}, {"role": "MANAGER", "permission": "orders.create"}, {"role": "MANAGER", "permission": "orders.export"}, {"role": "MANAGER", "permission": "orders.fulfill"}, {"role": "MANAGER", "permission": "orders.status"}, {"role": "MANAGER", "permission": "orders.update"}, {"role": "MANAGER", "permission": "orders.view"}, {"role": "MANAGER", "permission": "payments.record"}, {"role": "MANAGER", "permission": "pbx.call"}, {"role": "MANAGER", "permission": "production.manage"}, {"role": "MANAGER", "permission": "production.view"}, {"role": "MANAGER", "permission": "products.view"}, {"role": "MANAGER", "permission": "purchases.view"}, {"role": "MANAGER", "permission": "reports.export"}, {"role": "MANAGER", "permission": "reports.view"}, {"role": "MANAGER", "permission": "settings.view"}, {"role": "MANAGER", "permission": "shipments.manage"}, {"role": "MANAGER", "permission": "sms.view"}, {"role": "ORDER_MANAGER", "permission": "couriers.view"}, {"role": "ORDER_MANAGER", "permission": "customers.manage"}, {"role": "ORDER_MANAGER", "permission": "customers.view"}, {"role": "ORDER_MANAGER", "permission": "dashboard.view"}, {"role": "ORDER_MANAGER", "permission": "fraud.review"}, {"role": "ORDER_MANAGER", "permission": "fraud.view"}, {"role": "ORDER_MANAGER", "permission": "inventory.view"}, {"role": "ORDER_MANAGER", "permission": "orders.assign"}, {"role": "ORDER_MANAGER", "permission": "orders.block"}, {"role": "ORDER_MANAGER", "permission": "orders.cancel"}, {"role": "ORDER_MANAGER", "permission": "orders.create"}, {"role": "ORDER_MANAGER", "permission": "orders.export"}, {"role": "ORDER_MANAGER", "permission": "orders.fulfill"}, {"role": "ORDER_MANAGER", "permission": "orders.status"}, {"role": "ORDER_MANAGER", "permission": "orders.update"}, {"role": "ORDER_MANAGER", "permission": "orders.view"}, {"role": "ORDER_MANAGER", "permission": "payments.record"}, {"role": "ORDER_MANAGER", "permission": "payments.verify"}, {"role": "ORDER_MANAGER", "permission": "pbx.call"}, {"role": "ORDER_MANAGER", "permission": "production.view"}, {"role": "ORDER_MANAGER", "permission": "products.view"}, {"role": "ORDER_MANAGER", "permission": "shipments.manage"}, {"role": "ORDER_MANAGER", "permission": "sms.view"}, {"role": "PRODUCTION_MANAGER", "permission": "dashboard.view"}, {"role": "PRODUCTION_MANAGER", "permission": "inventory.view"}, {"role": "PRODUCTION_MANAGER", "permission": "orders.fulfill"}, {"role": "PRODUCTION_MANAGER", "permission": "orders.view"}, {"role": "PRODUCTION_MANAGER", "permission": "production.manage"}, {"role": "PRODUCTION_MANAGER", "permission": "production.view"}, {"role": "PRODUCTION_MANAGER", "permission": "products.view"}, {"role": "VIEWER", "permission": "couriers.view"}, {"role": "VIEWER", "permission": "customers.view"}, {"role": "VIEWER", "permission": "dashboard.view"}, {"role": "VIEWER", "permission": "inventory.view"}, {"role": "VIEWER", "permission": "orders.view"}, {"role": "VIEWER", "permission": "production.view"}, {"role": "VIEWER", "permission": "products.view"}, {"role": "VIEWER", "permission": "reports.view"}]$d$::jsonb) d(role text, permission text)
  join public.roles r on r.merchant_id = p_merchant and r.code = d.role
  join public.permissions p on p.code = d.permission
  on conflict do nothing;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('role_permissions', v_n);

  insert into public.order_review_statuses (merchant_id, code, label, description, color, closes_order, needs_follow_up, counts_contact, is_system, is_active, sort_order)
  select p_merchant, d.code, d.label, d.description, d.color, d.closes_order, d.needs_follow_up, d.counts_contact, d.is_system, d.is_active, d.sort_order
  from jsonb_populate_recordset(null::public.order_review_statuses, $d$[{"code": "PROCESSING", "color": "info", "label": "Processing", "is_active": true, "is_system": true, "sort_order": 10, "description": "New, or being handled", "closes_order": false, "counts_contact": false, "needs_follow_up": false}, {"code": "GOOD_NO_RESPONSE", "color": "violet", "label": "Good but no response", "is_active": true, "is_system": true, "sort_order": 20, "description": "Good courier history, but did not pick up", "closes_order": false, "counts_contact": true, "needs_follow_up": false}, {"code": "NO_RESPONSE", "color": "warning", "label": "No response", "is_active": true, "is_system": true, "sort_order": 30, "description": "Did not pick up the call", "closes_order": false, "counts_contact": true, "needs_follow_up": false}, {"code": "FOLLOW_UP", "color": "info", "label": "Follow-up", "is_active": true, "is_system": true, "sort_order": 40, "description": "Call back at an agreed time", "closes_order": false, "counts_contact": false, "needs_follow_up": true}, {"code": "DUPLICATE", "color": "neutral", "label": "Duplicate", "is_active": true, "is_system": true, "sort_order": 80, "description": "The customer ordered the same thing again", "closes_order": true, "counts_contact": false, "needs_follow_up": false}, {"code": "INVALID", "color": "danger", "label": "Invalid", "is_active": true, "is_system": true, "sort_order": 85, "description": "Fake, prank or unusable details", "closes_order": true, "counts_contact": false, "needs_follow_up": false}, {"code": "CANCELLED", "color": "neutral", "label": "Cancelled", "is_active": true, "is_system": true, "sort_order": 90, "description": "Cancelled before approval", "closes_order": true, "counts_contact": false, "needs_follow_up": false}, {"code": "OLD_CANCELLED", "color": "neutral", "label": "Old cancelled", "is_active": true, "is_system": true, "sort_order": 95, "description": "Went stale without an answer and was closed", "closes_order": true, "counts_contact": false, "needs_follow_up": false}]$d$::jsonb) d
  on conflict do nothing;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('order_review_statuses', v_n);

  insert into public.order_sources (merchant_id, code, label, channel, is_active, sort_order, is_system)
  select p_merchant, d.code, d.label, d.channel, d.is_active, d.sort_order, d.is_system
  from jsonb_populate_recordset(null::public.order_sources, $d$[{"code": "MESSENGER", "label": "Messenger", "channel": "messaging", "is_active": true, "is_system": true, "sort_order": 10}, {"code": "WHATSAPP", "label": "WhatsApp", "channel": "messaging", "is_active": true, "is_system": true, "sort_order": 20}, {"code": "PHONE", "label": "Phone call", "channel": "phone", "is_active": true, "is_system": true, "sort_order": 30}, {"code": "FACEBOOK_COMMENT", "label": "Facebook", "channel": "organic_social", "is_active": true, "is_system": true, "sort_order": 40}, {"code": "INSTAGRAM_DM", "label": "Instagram", "channel": "messaging", "is_active": true, "is_system": true, "sort_order": 50}, {"code": "WALK_IN", "label": "Walk-in", "channel": "offline", "is_active": true, "is_system": true, "sort_order": 60}, {"code": "REFERRAL", "label": "Referral", "channel": "referral", "is_active": true, "is_system": true, "sort_order": 70}, {"code": "REPEAT_CUSTOMER", "label": "Repeat customer", "channel": "direct", "is_active": true, "is_system": true, "sort_order": 80}, {"code": "OTHER", "label": "Other", "channel": "other", "is_active": true, "is_system": true, "sort_order": 90}]$d$::jsonb) d
  on conflict do nothing;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('order_sources', v_n);

  insert into public.finance_categories (merchant_id, code, name, type, pnl_group, description, is_system, allow_manual, is_active, sort_order, color, subcategories)
  select p_merchant, d.code, d.name, d.type, d.pnl_group, d.description, d.is_system, d.allow_manual, d.is_active, d.sort_order, d.color, d.subcategories
  from jsonb_populate_recordset(null::public.finance_categories, $d$[{"code": "PRODUCT_SALES", "name": "Product Sales", "type": "INCOME", "color": "violet", "is_active": true, "is_system": true, "pnl_group": "REVENUE", "sort_order": 10, "description": "Recognised automatically when an order is delivered", "allow_manual": false, "subcategories": []}, {"code": "DELIVERY_CHARGES", "name": "Delivery Charges", "type": "INCOME", "color": "blue", "is_active": true, "is_system": true, "pnl_group": "DELIVERY_INCOME", "sort_order": 20, "description": "Delivery fee charged to customers on delivered orders", "allow_manual": false, "subcategories": []}, {"code": "ADVANCE_PAYMENTS", "name": "Advance Payments", "type": "INCOME", "color": "teal", "is_active": true, "is_system": true, "pnl_group": "NONE", "sort_order": 30, "description": "Cash received before delivery (not revenue until delivered)", "allow_manual": false, "subcategories": []}, {"code": "ONLINE_PAYMENTS", "name": "Online Payments", "type": "INCOME", "color": "amber", "is_active": true, "is_system": true, "pnl_group": "NONE", "sort_order": 40, "description": "Full or balance payments received online", "allow_manual": false, "subcategories": []}, {"code": "COD_COLLECTIONS", "name": "COD Collections", "type": "INCOME", "color": "orange", "is_active": true, "is_system": true, "pnl_group": "NONE", "sort_order": 50, "description": "Cash on delivery settled by couriers", "allow_manual": false, "subcategories": []}, {"code": "RETAINED_ADVANCES", "name": "Retained Advances", "type": "INCOME", "color": "red", "is_active": true, "is_system": true, "pnl_group": "OTHER_INCOME", "sort_order": 60, "description": "Advances kept after cancellation/return", "allow_manual": false, "subcategories": []}, {"code": "COURIER_CLAIMS", "name": "Courier claims", "type": "INCOME", "color": "emerald", "is_active": true, "is_system": true, "pnl_group": "OTHER_INCOME", "sort_order": 65, "description": "Compensation from couriers for lost or damaged parcels", "allow_manual": true, "subcategories": []}, {"code": "OTHER_INCOME", "name": "Other Income", "type": "INCOME", "color": "pink", "is_active": true, "is_system": true, "pnl_group": "OTHER_INCOME", "sort_order": 70, "description": null, "allow_manual": true, "subcategories": []}, {"code": "INCOME_OTHER", "name": "Other", "type": "INCOME", "color": "cyan", "is_active": true, "is_system": true, "pnl_group": "OTHER_INCOME", "sort_order": 80, "description": null, "allow_manual": true, "subcategories": []}, {"code": "PRODUCT_PURCHASE", "name": "Product Purchase", "type": "EXPENSE", "color": "violet", "is_active": true, "is_system": true, "pnl_group": "NONE", "sort_order": 100, "description": "Stock purchases; cost reaches P&L as COGS on delivery", "allow_manual": true, "subcategories": []}, {"code": "COGS", "name": "Cost of Goods Sold", "type": "EXPENSE", "color": "blue", "is_active": true, "is_system": true, "pnl_group": "COGS", "sort_order": 110, "description": "Posted automatically on delivery", "allow_manual": false, "subcategories": []}, {"code": "LOST_PARCELS", "name": "Lost parcels", "type": "EXPENSE", "color": "teal", "is_active": true, "is_system": true, "pnl_group": "COGS", "sort_order": 115, "description": "Cost of goods a courier lost", "allow_manual": false, "subcategories": []}, {"code": "PRODUCTION_COST", "name": "Production Cost", "type": "EXPENSE", "color": "amber", "is_active": true, "is_system": true, "pnl_group": "COGS", "sort_order": 120, "description": null, "allow_manual": true, "subcategories": []}, {"code": "PACKAGING", "name": "Packaging", "type": "EXPENSE", "color": "orange", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 130, "description": null, "allow_manual": true, "subcategories": []}, {"code": "COURIER", "name": "Courier", "type": "EXPENSE", "color": "red", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 140, "description": null, "allow_manual": true, "subcategories": []}, {"code": "COD_FEES", "name": "COD fees", "type": "EXPENSE", "color": "emerald", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 145, "description": "Courier fee for collecting cash on delivery", "allow_manual": true, "subcategories": []}, {"code": "PAYMENT_FEES", "name": "Payment gateway fees", "type": "EXPENSE", "color": "pink", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 145, "description": "Fees on online payments, posted automatically from the % set per gateway in Settings → Payments", "allow_manual": true, "subcategories": []}, {"code": "ADVERTISING", "name": "Advertising", "type": "EXPENSE", "color": "cyan", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 150, "description": "Ad spend entries are posted automatically from Marketing", "allow_manual": true, "subcategories": []}, {"code": "SMS", "name": "SMS", "type": "EXPENSE", "color": "lime", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 155, "description": "Cost of each SMS sent to customers, posted automatically (do not add SMS top-ups as expenses)", "allow_manual": false, "subcategories": []}, {"code": "SALARIES", "name": "Salaries", "type": "EXPENSE", "color": "indigo", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 160, "description": null, "allow_manual": true, "subcategories": []}, {"code": "SOFTWARE", "name": "Software", "type": "EXPENSE", "color": "rose", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 170, "description": null, "allow_manual": true, "subcategories": []}, {"code": "HOSTING", "name": "Hosting", "type": "EXPENSE", "color": "sky", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 180, "description": null, "allow_manual": true, "subcategories": []}, {"code": "RENT", "name": "Rent", "type": "EXPENSE", "color": "yellow", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 190, "description": null, "allow_manual": true, "subcategories": []}, {"code": "UTILITIES", "name": "Utilities", "type": "EXPENSE", "color": "fuchsia", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 200, "description": null, "allow_manual": true, "subcategories": []}, {"code": "REFUNDS", "name": "Refunds", "type": "EXPENSE", "color": "slate", "is_active": true, "is_system": true, "pnl_group": "CONTRA_REVENUE", "sort_order": 210, "description": "Refunds on delivered orders (reduce revenue)", "allow_manual": false, "subcategories": []}, {"code": "PARTIAL_RETURNS", "name": "Partial delivery returns", "type": "EXPENSE", "color": "violet", "is_active": true, "is_system": true, "pnl_group": "CONTRA_REVENUE", "sort_order": 215, "description": "Goods sent back on a partial delivery (reduces revenue)", "allow_manual": false, "subcategories": []}, {"code": "ADVANCE_REFUNDS", "name": "Advance Refunds", "type": "EXPENSE", "color": "blue", "is_active": true, "is_system": true, "pnl_group": "NONE", "sort_order": 220, "description": "Advances returned on undelivered orders", "allow_manual": false, "subcategories": []}, {"code": "RETURNS", "name": "Returns", "type": "EXPENSE", "color": "teal", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 230, "description": "Return shipping and return-related costs", "allow_manual": true, "subcategories": []}, {"code": "EXPENSE_OTHER", "name": "Other", "type": "EXPENSE", "color": "amber", "is_active": true, "is_system": true, "pnl_group": "OPERATING_EXPENSE", "sort_order": 240, "description": null, "allow_manual": true, "subcategories": []}]$d$::jsonb) d
  on conflict do nothing;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('finance_categories', v_n);

  if not exists (select 1 from public.fraud_rules where merchant_id = p_merchant) then
    insert into public.fraud_rules (merchant_id, name, description, priority, match_mode, conditions, is_active)
    select p_merchant, d.name, d.description, d.priority, d.match_mode, d.conditions, d.is_active
    from jsonb_populate_recordset(null::public.fraud_rules, $d$[{"name": "Blocked customer", "priority": 10, "is_active": true, "conditions": [{"op": "is_true", "field": "phone_flagged"}], "match_mode": "ALL", "description": "Phone number belongs to a blocked customer"}, {"name": "Critical risk", "priority": 20, "is_active": true, "conditions": [{"op": "eq", "field": "risk_level", "value": "CRITICAL"}], "match_mode": "ALL", "description": "Send to manual review; suggest delivery + return charge as advance"}, {"name": "High risk", "priority": 30, "is_active": true, "conditions": [{"op": "eq", "field": "risk_level", "value": "HIGH"}], "match_mode": "ALL", "description": "Advance of the delivery charge before confirming"}, {"name": "Repeated failed COD", "priority": 40, "is_active": true, "conditions": [{"op": "gte", "field": "failed_cod_orders", "value": 2}], "match_mode": "ALL", "description": "Two or more COD parcels refused/failed before"}, {"name": "New customer, high order value", "priority": 50, "is_active": true, "conditions": [{"op": "is_true", "field": "is_new_customer"}, {"op": "gte", "field": "order_value", "value": 5000}], "match_mode": "ALL", "description": "First order above 5,000"}, {"name": "Medium risk", "priority": 60, "is_active": true, "conditions": [{"op": "eq", "field": "risk_level", "value": "MEDIUM"}], "match_mode": "ALL", "description": "Cash on delivery allowed (change to an advance if needed)"}, {"name": "Low risk", "priority": 70, "is_active": true, "conditions": [{"op": "eq", "field": "risk_level", "value": "LOW"}], "match_mode": "ALL", "description": "Normal cash on delivery"}]$d$::jsonb) d;
    insert into public.fraud_rule_actions (merchant_id, rule_id, decision, advance_type, advance_value, customer_message, stop_processing)
    select p_merchant, r.id, d.decision, d.advance_type, d.advance_value, d.customer_message, d.stop_processing
    from jsonb_to_recordset($d$[{"decision": "BLOCK", "rule_name": "Blocked customer", "advance_type": "NONE", "advance_value": 0.00, "stop_processing": true, "customer_message": null}, {"decision": "REVIEW", "rule_name": "Critical risk", "advance_type": "DELIVERY_PLUS_RETURN", "advance_value": 0.00, "stop_processing": false, "customer_message": null}, {"decision": "ADVANCE_REQUIRED", "rule_name": "High risk", "advance_type": "DELIVERY_CHARGE", "advance_value": 0.00, "stop_processing": false, "customer_message": null}, {"decision": "ADVANCE_REQUIRED", "rule_name": "Repeated failed COD", "advance_type": "DELIVERY_PLUS_RETURN", "advance_value": 0.00, "stop_processing": false, "customer_message": null}, {"decision": "ADVANCE_REQUIRED", "rule_name": "New customer, high order value", "advance_type": "PERCENTAGE", "advance_value": 20.00, "stop_processing": false, "customer_message": null}, {"decision": "ALLOW", "rule_name": "Medium risk", "advance_type": "NONE", "advance_value": 0.00, "stop_processing": false, "customer_message": null}, {"decision": "ALLOW", "rule_name": "Low risk", "advance_type": "NONE", "advance_value": 0.00, "stop_processing": false, "customer_message": null}]$d$::jsonb) d(rule_name text, decision public.fraud_decision,
      advance_type public.advance_type, advance_value numeric, customer_message text, stop_processing boolean)
    join public.fraud_rules r on r.merchant_id = p_merchant and r.name = d.rule_name;
    v_counts := v_counts || jsonb_build_object('fraud_rules', (select count(*) from public.fraud_rules where merchant_id = p_merchant));
  end if;

  if not exists (select 1 from public.delivery_zones where merchant_id = p_merchant) then
    insert into public.delivery_zones (merchant_id, name, districts, areas, charge, return_charge, estimated_days, is_default, is_active, sort_order)
    select p_merchant, d.name, d.districts, d.areas, d.charge, d.return_charge, d.estimated_days, d.is_default, d.is_active, d.sort_order
    from jsonb_populate_recordset(null::public.delivery_zones, $d$[{"name": "Inside Dhaka", "areas": [], "charge": 80.00, "districts": ["dhaka"], "is_active": true, "is_default": false, "sort_order": 1, "return_charge": 50.00, "estimated_days": "1–2 days"}, {"name": "Dhaka suburbs", "areas": [], "charge": 110.00, "districts": ["gazipur", "narayanganj", "savar"], "is_active": true, "is_default": false, "sort_order": 2, "return_charge": 60.00, "estimated_days": "2–3 days"}, {"name": "Outside Dhaka", "areas": [], "charge": 130.00, "districts": [], "is_active": true, "is_default": true, "sort_order": 3, "return_charge": 80.00, "estimated_days": "3–5 days"}]$d$::jsonb) d;
    get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('delivery_zones', v_n);
  end if;

  if not exists (select 1 from public.couriers where merchant_id = p_merchant) then
    insert into public.couriers (merchant_id, name, provider, api_enabled, api_status, tracking_url_template, phone, notes, config, default_shipping_cost, is_active)
    select p_merchant, d.name, d.provider, d.api_enabled, d.api_status, d.tracking_url_template, d.phone, d.notes, d.config, d.default_shipping_cost, d.is_active
    from jsonb_populate_recordset(null::public.couriers, $d$[{"name": "Own delivery", "notes": "Deliveries handled by your own team or a courier without API integration", "phone": null, "config": {}, "provider": "manual", "is_active": true, "api_status": "NOT_CONFIGURED", "api_enabled": false, "api_checked_at": null, "default_shipping_cost": null, "tracking_url_template": null}]$d$::jsonb) d;
    get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('couriers', v_n);
  end if;

  if not exists (select 1 from public.notifications where merchant_id = p_merchant) then
    insert into public.notifications (merchant_id, event, channel, is_enabled, subject, template, name, conditions)
    select p_merchant, d.event, d.channel, d.is_enabled, d.subject, d.template, d.name, d.conditions
    from jsonb_populate_recordset(null::public.notifications, $d$[{"name": "Order placed", "event": "ORDER_CREATED", "channel": "SMS", "subject": null, "template": "Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order placed", "event": "ORDER_CREATED", "channel": "WHATSAPP", "subject": null, "template": "Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order placed", "event": "ORDER_CREATED", "channel": "EMAIL", "subject": "We received your order {{order_number}}", "template": "Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order approved", "event": "ORDER_CONFIRMED", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order approved", "event": "ORDER_CONFIRMED", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order approved", "event": "ORDER_CONFIRMED", "channel": "EMAIL", "subject": "Order {{order_number}} confirmed", "template": "Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Pre-order confirmed", "event": "PRE_ORDER_CONFIRMED", "channel": "SMS", "subject": null, "template": "Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Pre-order confirmed", "event": "PRE_ORDER_CONFIRMED", "channel": "WHATSAPP", "subject": null, "template": "Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Pre-order confirmed", "event": "PRE_ORDER_CONFIRMED", "channel": "EMAIL", "subject": "Pre-order {{order_number}} confirmed", "template": "Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Advance needed", "event": "ADVANCE_REQUIRED", "channel": "SMS", "subject": null, "template": "To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Advance needed", "event": "ADVANCE_REQUIRED", "channel": "WHATSAPP", "subject": null, "template": "To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Advance needed", "event": "ADVANCE_REQUIRED", "channel": "EMAIL", "subject": "Advance payment needed for {{order_number}}", "template": "To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment received", "event": "PAYMENT_RECEIVED", "channel": "SMS", "subject": null, "template": "We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment received", "event": "PAYMENT_RECEIVED", "channel": "WHATSAPP", "subject": null, "template": "We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment received", "event": "PAYMENT_RECEIVED", "channel": "EMAIL", "subject": "Payment received for {{order_number}}", "template": "We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment failed", "event": "PAYMENT_FAILED", "channel": "SMS", "subject": null, "template": "Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment failed", "event": "PAYMENT_FAILED", "channel": "WHATSAPP", "subject": null, "template": "Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Payment failed", "event": "PAYMENT_FAILED", "channel": "EMAIL", "subject": "Payment for {{order_number}} did not go through", "template": "Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order shipped", "event": "ORDER_SHIPPED", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order shipped", "event": "ORDER_SHIPPED", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order shipped", "event": "ORDER_SHIPPED", "channel": "EMAIL", "subject": "Order {{order_number}} is on the way", "template": "Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Out for delivery", "event": "OUT_FOR_DELIVERY", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Out for delivery", "event": "OUT_FOR_DELIVERY", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Out for delivery", "event": "OUT_FOR_DELIVERY", "channel": "EMAIL", "subject": "Order {{order_number}} is out for delivery", "template": "Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Delivered", "event": "ORDER_DELIVERED", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Delivered", "event": "ORDER_DELIVERED", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Delivered", "event": "ORDER_DELIVERED", "channel": "EMAIL", "subject": "Order {{order_number}} delivered", "template": "Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order cancelled", "event": "ORDER_CANCELLED", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order cancelled", "event": "ORDER_CANCELLED", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Order cancelled", "event": "ORDER_CANCELLED", "channel": "EMAIL", "subject": "Order {{order_number}} cancelled", "template": "Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Return initiated", "event": "RETURN_INITIATED", "channel": "SMS", "subject": null, "template": "Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Return initiated", "event": "RETURN_INITIATED", "channel": "WHATSAPP", "subject": null, "template": "Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Return initiated", "event": "RETURN_INITIATED", "channel": "EMAIL", "subject": "Order {{order_number}} is being returned", "template": "Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Returned", "event": "ORDER_RETURNED", "channel": "SMS", "subject": null, "template": "We have received the return for order {{order_number}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Returned", "event": "ORDER_RETURNED", "channel": "WHATSAPP", "subject": null, "template": "We have received the return for order {{order_number}}. - {{store_name}}", "conditions": [], "is_enabled": false}, {"name": "Returned", "event": "ORDER_RETURNED", "channel": "EMAIL", "subject": "Return received for {{order_number}}", "template": "We have received the return for order {{order_number}}. - {{store_name}}", "conditions": [], "is_enabled": false}]$d$::jsonb) d;
    get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('notifications', v_n);
  end if;

  insert into public.settings (merchant_id, key, value, is_public, description)
  select p_merchant, d.key, d.value, d.is_public, d.description
