-- Re-owns every SECURITY DEFINER function in public that is not exempt. Later
-- migrations call it after adding functions.
create or replace function public._tenancy_own_functions()
returns integer
language plpgsql
set search_path = public, pg_temp
as $$
declare
  r record;
  v_n int := 0;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and p.prosecdef
      and p.proowner <> 'app_owner'::regrole
      and not exists (select 1 from public.tenancy_exempt_functions e where e.name = p.proname)
  loop
    execute format('alter function %s owner to app_owner', r.sig);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;
revoke execute on function public._tenancy_own_functions() from public, anon, authenticated, service_role;

select public._tenancy_own_functions();

-- Every table is either a tenant table (merchant_id + isolation policy) or listed as shared.
do $$
declare
  v_missing text;
begin
  select string_agg(c.relname, ', ') into v_missing
  from pg_class c
  where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
    and c.relname <> all (public._tenancy_global_tables())
    and (not exists (select 1 from pg_attribute a where a.attrelid = c.oid and a.attname = 'merchant_id' and not a.attisdropped)
         or not exists (select 1 from pg_policies p where p.schemaname = 'public' and p.tablename = c.relname
                        and p.policyname = 'tenant_isolation' and p.permissive = 'RESTRICTIVE'));
  if v_missing is not null then
    raise exception 'tenancy: tables without merchant isolation: %', v_missing;
  end if;
end $$;
